def load_lin(sym, need):
    d = f"{root}/bybit-linear/{sym}"
    A = []
    for fn in sorted(os.listdir(d)) if os.path.isdir(d) else []:
        with gzip.open(f"{d}/{fn}", "rt") as f:
            f.readline()
            for ln in f:
                p = ln.split(",", 10)
                t = float(p[0])
                if int(t // 60) in need:
                    A.extend((t, float(p[4]), float(p[9]), p[2] == "Buy"))
    return np.array(A, dtype=float).reshape(-1, 4) if A else None


def load_spot(sym, need):
    fn = f"{root}/bybit-spot/{sym}/{sym}-2026-09.csv.gz"
    if not os.path.exists(fn):
        return None
    A = []
    with gzip.open(fn, "rt") as f:
        f.readline()
        for ln in f:
            p = ln.split(",", 5)
            t = int(p[1]) / 1000.0
            if int(t // 60) in need:
                pr = float(p[2])
                A.extend((t, pr, pr * float(p[3]), p[4].strip() == "buy"))
    return np.array(A, dtype=float).reshape(-1, 4) if A else None


def win(A, lo, hi):
    t = A[:, 0]
    i, j = np.searchsorted(t, lo * 60.0), np.searchsorted(t, (hi + 1) * 60.0)
    return A[i:j]


def stats(w):
    if len(w) == 0:
        return None
    tot = w[:, 2].sum()
    buy = w[w[:, 3] == 1, 2].sum()
    return dict(bs=buy / tot if tot > 0 else np.nan, n=len(w), dl=(tot - 2 * buy) / tot if tot > 0 else np.nan)


